import React from 'react';
import './Pages.css';

function Home({ lang }) {
  return (
    <div className="home">
      <h1>
        {lang === 'ru'
          ? 'Добро пожаловать в нашу кофейню'
          : 'Welcome to our coffee shop'}
      </h1>

      {/* Текст-слоган */}
      <p className="slogan">
        {lang === 'ru'
          ? 'Лучший кофе в городе'
          : 'The best coffee in town'}
      </p>

      {/* Изображение чашки кофе */}
      <div className="coffee-image-container">
        <img
          src="/coffee-cup.svg"
          alt="Чашка кофе с паром"
          className="coffee-image"
        />
      </div>

      {/* Описание кофейни */}
      <p className="description">
        {lang === 'ru'
          ? 'Уютная атмосфера, свежая выпечка и авторские напитки'
          : 'Cozy atmosphere, fresh pastries and author\'s drinks'}
      </p>

      {/* Часы работы */}
      <p className="work-hours">
        🕒 {lang === 'ru'
          ? 'Работаем ежедневно с 8:00 до 22:00'
          : 'Open daily from 8:00 AM to 10:00 PM'}
      </p>

      {/* Девиз */}
      <p className="motto">
        {lang === 'ru'
          ? '«Наш девиз: Кофе, который вдохновляет»'
          : '"Our motto: Coffee that inspires"'}
      </p>
    </div>
  );
}

export default Home;
